using PlatformerSandbox.Foundation.Geometry;
using PlatformerSandbox.Simulation.Collision.Detection;
using PlatformerSandbox.Simulation.Collision.Resolution;
using PlatformerSandbox.Simulation.Motion.Profiles;

namespace PlatformerSandbox.Simulation.CharacterMotor;

/// <summary>
/// Bridges a configured jump reference to collision events. If an impact is
/// detected, evaluates the exact state at that instant and applies the chosen
/// pure velocity response. Deliberately stops at first contact: post-contact
/// motion must be generated by the authoritative motor, not by reusing a now
/// invalid designer reference path.
/// </summary>
public static class JumpReferenceInterruption
{
    public static JumpReferenceInterruptionResult AdvanceToFirstContact(
        Aabb initialBounds,
        JumpReferenceCollisionPlan plan,
        IReadOnlyList<StaticAabbCollider> obstacles,
        CollisionResponseMode responseMode = CollisionResponseMode.Slide,
        double contactAlignmentTolerance = 1e-8)
    {
        if (!Enum.IsDefined(responseMode))
            throw new ArgumentOutOfRangeException(nameof(responseMode));
        var hit = JumpProfileCollisionDetector.SweepFirst(
            initialBounds, plan, obstacles, contactAlignmentTolerance);
        if (hit is { } eventHit)
        {
            Vector2D outgoing = CollisionResponse.Apply(
                eventHit.VelocityAtImpact, eventHit.Normal, responseMode);
            return new JumpReferenceInterruptionResult(
                eventHit.MovingBoundsAtImpact, outgoing,
                eventHit.TimeSeconds,
                plan.TotalDurationSeconds - eventHit.TimeSeconds,
                eventHit);
        }

        JumpTravelSample end = plan.Reference.Evaluate(plan.TotalDurationSeconds);
        return new JumpReferenceInterruptionResult(
            initialBounds.Translated(new Vector2D(end.HorizontalPosition, end.VerticalDisplacement)),
            new Vector2D(end.HorizontalVelocity, end.VerticalVelocity),
            plan.TotalDurationSeconds, 0.0, null);
    }
}
